tinymce.PluginManager.add("mc_ai_gemini",function(editor,url){if(typeof window.MagixCMS!=="undefined"&&window.MagixCMS.ai_enabled===false){return}editor.ui.registry.addIcon("gemini-icon",'<svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L14.5 9.5L22 12L14.5 14.5L12 22L9.5 14.5L2 12L9.5 9.5L12 2Z" fill="#4285F4"/></svg>');const getCsrfToken=function(){const meta=document.querySelector('meta[name="csrf-token"]');if(meta&&meta.getAttribute("content")){return meta.getAttribute("content")}const hiddenToken=document.querySelector('input[name="hashtoken"]');return hiddenToken?hiddenToken.value:""};const openAiDialog=function(){const selectedText=editor.selection.getContent({format:"html"});let currentController=null;let currentTimeoutId=null;const cancelPendingRequest=function(){if(currentTimeoutId){clearTimeout(currentTimeoutId);currentTimeoutId=null}if(currentController){currentController.abort();currentController=null}};editor.windowManager.open({title:"Assistant Rédactionnel Magix AI",size:"large",body:{type:"panel",items:[{type:"grid",columns:2,items:[{type:"selectbox",name:"action_type",label:"Action",items:[{text:"Rédaction / Correction",value:"write"},{text:"Traduire vers...",value:"translate"}]},{type:"selectbox",name:"language",label:"Langue cible",items:[{text:"Français",value:"français"},{text:"Anglais",value:"anglais"},{text:"Néerlandais",value:"néerlandais"},{text:"Allemand",value:"allemand"}]},{type:"selectbox",name:"tone",label:"Ton du texte",items:[{text:"Professionnel",value:"professionnel"},{text:"Amical",value:"amical"},{text:"Marketing",value:"marketing"}]},{type:"selectbox",name:"length",label:"Longueur",items:[{text:"Standard",value:"standard"},{text:"Court",value:"court"},{text:"Détaillé",value:"long"}]}]},{type:"textarea",name:"prompt",label:"Instruction pour l'IA",placeholder:"Ex: Rédige un paragraphe sur le référencement, traduis ce texte..."},{type:"htmlpanel",html:'<div style="margin: 10px 0; border-top: 1px solid #ddd;"></div>'},{type:"textarea",name:"result",label:"Contenu généré (HTML)",placeholder:"Le résultat s'affichera ici...",flex:true}]},buttons:[{type:"custom",name:"generate_btn",text:"Générer",primary:true},{type:"submit",name:"insert_btn",text:"Insérer dans la page",enabled:false},{type:"cancel",text:"Annuler"}],onAction:function(api,details){if(details.name!=="generate_btn"){return}const data=api.getData();const promptText=(data.prompt||"").trim();if(!promptText&&!selectedText){editor.notificationManager.open({text:"Veuillez saisir une instruction ou sélectionner du texte.",type:"warning"});return}const csrfToken=getCsrfToken();if(!csrfToken){editor.notificationManager.open({text:"Jeton de sécurité (CSRF) introuvable. Veuillez recharger la page.",type:"error"});return}cancelPendingRequest();currentController=new AbortController;let timedOut=false;currentTimeoutId=setTimeout(function(){timedOut=true;if(currentController){currentController.abort()}},65e3);api.block("L'IA Magix prépare votre contenu...");fetch("index.php?controller=GeminiAI&action=generate",{method:"POST",signal:currentController.signal,headers:{"Content-Type":"application/json","X-CSRF-Token":csrfToken},body:JSON.stringify({hashtoken:csrfToken,prompt:promptText,context:selectedText,options:{action_type:data.action_type,language:data.language,tone:data.tone,length:data.length}})}).then(function(res){return res.text().then(function(rawText){let parsed=null;try{parsed=JSON.parse(rawText)}catch(e){throw new Error("Réponse serveur invalide (HTTP "+res.status+").")}if(!res.ok&&!parsed.message){throw new Error("Erreur HTTP "+res.status)}return parsed})}).then(function(resData){if((resData.status||resData.success)&&resData.content){api.setData({result:resData.content});api.setEnabled("insert_btn",true)}else{const errorMsg=resData.message||"Erreur inconnue retournée par l'API.";editor.notificationManager.open({text:errorMsg,type:"error"})}}).catch(function(err){if(err.name==="AbortError"){if(timedOut){editor.notificationManager.open({text:"Délai d'attente dépassé lors de la génération. Essayez un texte plus court ou le modèle Flash-Lite.",type:"error"})}return}console.error("GeminiAI Fetch Error:",err);editor.notificationManager.open({text:err.message||"Erreur de communication avec le serveur Magix CMS.",type:"error"})}).finally(function(){if(currentTimeoutId){clearTimeout(currentTimeoutId);currentTimeoutId=null}currentController=null;api.unblock()})},onSubmit:function(api){const data=api.getData();if(data.result){editor.undoManager.transact(function(){editor.insertContent(data.result)});api.close()}},onClose:function(){cancelPendingRequest()}})};editor.ui.registry.addButton("mc_ai_gemini",{icon:"gemini-icon",tooltip:"Assistant IA Magix",onAction:openAiDialog});editor.ui.registry.addMenuItem("mc_ai_gemini",{text:"Assistant IA Magix",icon:"gemini-icon",onAction:openAiDialog})});